INSERT INTO memories(kind, content) VALUES('kb', 'Tỷ lệ RR tối thiểu: scalping 1:1.5 trở lên, swing 1:2 trở lên, setup đẹp 1:3+. Không bao giờ nhận lệnh RR dưới 1:1 dù tin chắc đến đâu.');
INSERT INTO memories(kind, content) VALUES('kb', 'Position size theo công thức: khối lượng = rủi ro tối đa ($) / khoảng cách SL (giá). SL càng xa thì volume càng nhỏ, không bao giờ cố định lot.');
INSERT INTO memories(kind, content) VALUES('kb', 'Quy tắc sống còn: tối đa 2% tài khoản mỗi lệnh, tối đa 6% rủi ro mở cùng lúc, thua 3 lệnh liên tiếp thì nghỉ hết ngày. Báo thù thị trường là cách cháy nhanh nhất.');
INSERT INTO memories(kind, content) VALUES('kb', 'OTE (Optimal Trade Entry): pullback về vùng Fibonacci 0.62-0.79 của chân sóng khung lớn là entry swing xác suất cao, SL dưới chân sóng, TP đỉnh cũ.');
INSERT INTO memories(kind, content) VALUES('kb', 'Premium/Discount: chỉ buy ở vùng discount (dưới equilibrium range), chỉ sell ở premium (trên equilibrium). Mua giữa range khi giá chạy là đuổi giá.');
INSERT INTO memories(kind, content) VALUES('kb', 'Killzone theo giờ VN: Âu 14h-17h và Mỹ 19h30-23h là giờ vàng XAU/USD (biên lớn, spread thấp). Á sáng biên hẹp chỉ hợp scalping biên hoặc đứng ngoài.');
INSERT INTO memories(kind, content) VALUES('kb', 'Xác nhận đa khung: bias theo 4H/1D, timing theo 15m/5m. Không buy khi 4H đang phân phối đỉnh dù 1m đẹp; không sell khi 1D BOS lên trừ khi có CHoCH rõ.');
INSERT INTO memories(kind, content) VALUES('kb', 'Đo winrate theo RR mới có nghĩa: winrate 40% với RR 1:2 vẫn lãi dài hạn (kỳ vọng dương). Ghi nhật ký mọi lệnh: entry theo plan hay cảm tính.');
INSERT INTO memories(kind, content) VALUES('kb', 'Dời SL về entry (breakeven) khi giá đi đúng 1R, chốt 1/2 ở TP1 để lệnh không bao giờ từ lãi thành lỗ. Không dời TP xa hơn giữa chừng vì tham.');
INSERT INTO memories(kind, content) VALUES('kb', 'Tin đỏ (NFP/CPI/FOMC): spread XAU/USD có thể giãn gấp 5-10 lần, trượt giá mạnh. Lệnh chờ đặt trước tin phải tính spread giãn vào SL, hoặc đứng ngoài 30 phút.');
